class DataHelper {
   // returns users who haven't logged in for 30+ days
   getStuffFromMySQL(): User[] {
     const all = db.query('SELECT * FROM users');
     return all.filter(u => {
       const d = (Date.now() - u.lastLoginAt) / 86400000;
       return d > 30;
     });
   }
   // also: sends them a re-engagement email
   process(users: User[]): void {
     for (const u of users) mailer.send(u.email, 'We miss you');
   }
 }
